def f(g):
    h,w=len(g),len(g[0]); out=[r[:] for r in g]
    cnt=Counter(x for r in g for x in r); seed=min(cnt.items(), key=lambda t:t[1])[0]
    cells=[(i,j) for i in range(h) for j in range(w) if g[i][j]==seed]
    seen=set(cells); stack=list(cells)
    while stack:
        i,j=stack.pop()
        for di_,dj_ in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di_,j+dj_
            if 0<=a<h and 0<=b<w and (a,b) not in seen and g[a][b]==seed:
                seen.add((a,b)); stack.append((a,b))
    rs=[p[0] for p in seen]; cs=[p[1] for p in seen]
    top,bottom,left,right=min(rs),max(rs),min(cs),max(cs)
    for i in range(top,bottom+1): out[i][left]=out[i][right]=seed
    for j in range(left,right+1): out[top][j]=out[bottom][j]=seed
    return out
