def ray(r,c,tr,tc):
    u=1 if tr>r else -1 if tr<r else 0
    v=1 if tc>c else -1 if tc<c else 0
    x,y=r+u,c+v
    while (x,y)!=(tr,tc):
        if I[x][y]!=0: return False
        x+=u; y+=v
    return True
